import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string in xs as an integer and return their sum.

    Raises BadInput carrying the first string that is not a valid integer.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_parsed_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_negative() -> None:
    assert sum_parsed(["-5", "10"]) == 5


def test_sum_parsed_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["1", "x", "2"])
    assert excinfo.value.text == "x"


def test_sum_parsed_reports_first_bad_string() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["a", "b"])
    assert excinfo.value.text == "a"
